export const PROGRAM_NAME = 'test18_executable';
export const EXECUTABLE_PATH = '/workspace/dataset/test18_executable';

export const DEPRECATION_WARNING =
  'test18.py:4: DeprecationWarning: Importing ErrorTree directly from the jsonschema package is deprecated and will become an ImportError. Import it from jsonschema.exceptions instead.\n';

export const USAGE_LINE = `usage: ${PROGRAM_NAME} [-h] --a A --b B\n`;

export const HELP_TEXT =
  `${USAGE_LINE}\n` +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A       instance (JSON string)\n' +
  '  --b B       schema (JSON string)\n';

export const EXIT_SUCCESS = 0;
export const EXIT_PARSER_ERROR = 2;
export const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

import {
  DEPRECATION_WARNING,
  HELP_TEXT,
  PROGRAM_NAME,
  USAGE_LINE,
} from './constants.mjs';

export function writeWarning(stream = process.stderr) {
  stream.write(DEPRECATION_WARNING);
}

export function writeHelp() {
  writeWarning();
  process.stdout.write(HELP_TEXT);
}

export function writeArgumentError(message) {
  writeWarning();
  process.stderr.write(USAGE_LINE);
  process.stderr.write(`${PROGRAM_NAME}: error: ${message}\n`);
}

import { NEGATIVE_NUMBER_PATTERN } from './constants.mjs';

function isHelpToken(token) {
  return token === '-h' || token === '--help';
}

function readInlineValue(token, optionName) {
  const prefix = `${optionName}=`;
  return token.startsWith(prefix) ? token.slice(prefix.length) : null;
}

function isOptionLike(token) {
  return typeof token === 'string' && token.startsWith('-');
}

function isValueToken(token) {
  if (token === undefined) {
    return false;
  }

  return !isOptionLike(token) || NEGATIVE_NUMBER_PATTERN.test(token);
}

export function parseCommandLine(argv) {
  for (const token of argv) {
    if (isHelpToken(token)) {
      return { kind: 'help' };
    }
  }

  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--a' || token === '--b') {
      const nextToken = argv[index + 1];

      if (!isValueToken(nextToken)) {
        return {
          kind: 'error',
          message: `argument ${token}: expected one argument`,
        };
      }

      if (token === '--a') {
        a = nextToken;
      } else {
        b = nextToken;
      }

      index += 1;
      continue;
    }

    const inlineA = readInlineValue(token, '--a');
    if (inlineA !== null) {
      a = inlineA;
      continue;
    }

    const inlineB = readInlineValue(token, '--b');
    if (inlineB !== null) {
      b = inlineB;
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (a === undefined) {
    missing.push('--a');
  }
  if (b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'run',
    args: { a, b },
  };
}

import { parseCommandLine } from './lib/cli.mjs';
import {
  EXIT_PARSER_ERROR,
  EXIT_SUCCESS,
} from './lib/constants.mjs';
import { writeArgumentError, writeHelp } from './lib/messages.mjs';
import { runExecutable } from './lib/runner.mjs';

const outcome = parseCommandLine(process.argv.slice(2));

if (outcome.kind === 'help') {
  writeHelp();
  process.exit(EXIT_SUCCESS);
}

if (outcome.kind === 'error') {
  writeArgumentError(outcome.message);
  process.exit(EXIT_PARSER_ERROR);
}

process.exit(runExecutable(outcome.args));

import { spawnSync } from 'node:child_process';

import { EXECUTABLE_PATH } from './constants.mjs';

export function runExecutable({ a, b }) {
  const result = spawnSync(EXECUTABLE_PATH, ['--a', a, '--b', b], {
    stdio: 'inherit',
  });

  if (result.error) {
    throw result.error;
  }

  if (result.signal) {
    process.kill(process.pid, result.signal);
    return 1;
  }

  return result.status ?? 1;
}
